// lib/auth.ts (both frontends)
export const saveTokens = (tokens: IAuthTokens) => {
  localStorage.setItem('felly_access_token', tokens.accessToken);
  localStorage.setItem('felly_refresh_token', tokens.refreshToken);
};
export const getAccessToken = () => localStorage.getItem('felly_access_token');
export const clearTokens = () => {
  localStorage.removeItem('felly_access_token');
  localStorage.removeItem('felly_refresh_token');
};

